changeSet.sql:
-- Add tsvector column for full-text search
ALTER TABLE item ADD COLUMN search_vector tsvector;

-- Create function to update the search vector
CREATE OR REPLACE FUNCTION item_search_vector_update() RETURNS trigger AS $$
BEGIN
  NEW.search_vector =
    setweight(to_tsvector('simple', COALESCE(NEW.name, '')), 'A') ||
    setweight(to_tsvector('simple', COALESCE(NEW.description, '')), 'B');
RETURN NEW;
END
$$ LANGUAGE plpgsql;

-- Create trigger to automatically update the search vector
CREATE TRIGGER item_search_vector_update_trigger
    BEFORE INSERT OR UPDATE ON item
                         FOR EACH ROW EXECUTE FUNCTION item_search_vector_update();

-- Create GIN index for performance
CREATE INDEX item_search_idx ON item USING GIN(search_vector);
